import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.DoCD98hS.js";const k=JSON.parse('{"title":"梗图 · TierRanking / MonsterDeleter","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/meme.md","filePath":"modules/catalog/meme.md","lastUpdated":1795364242000}'),s={name:"modules/catalog/meme.md"};function r(i,e,c,n,l,h){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="梗图-·-tierranking-monsterdeleter" tabindex="-1">梗图 · TierRanking / MonsterDeleter <a class="header-anchor" href="#梗图-·-tierranking-monsterdeleter" aria-label="Permalink to &quot;梗图 · TierRanking / MonsterDeleter&quot;">​</a></h1><p>低频 / 梗图类组件的统一出口。当前有排行榜 <code>TierRanking</code>（从夯到拉，Vue 2 / Vue 3 双包）、怪兽摧毁文件剧场 <code>MonsterDeleter</code>（仅 Vue 3）与浓度校准器 <code>IntensityCalibrator</code>（仅 Vue 3）。</p><div class="info custom-block"><p class="custom-block-title">为什么单独成包</p><p><code>TierRanking</code> 属于低频交互，体积与依赖（IndexedDB、html2canvas 截图）都偏重；<code>MonsterDeleter</code> 是自包含的帧动画剧场，素材（spritesheet、音频）体积较大；<code>IntensityCalibrator</code> 随包带 12 张立绘。三者都不放进通用组件包（<code>comps-vue2</code> / <code>comps-vue2-ele</code> / <code>comps-vue2-antd</code> / <code>comps-vue3</code>），只保留在 meme 包里；通用包回归轻量与高频。</p></div><h2 id="包范围" tabindex="-1">包范围 <a class="header-anchor" href="#包范围" aria-label="Permalink to &quot;包范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包名</th><th>职责</th></tr></thead><tbody><tr><td><code>@melt-js/comps-vue3-meme</code></td><td>Vue 3 梗图组件，<code>TierRanking</code>、<code>MonsterDeleter</code>、<code>IntensityCalibrator</code> 完整实现</td></tr><tr><td><code>@melt-js/comps-vue2-meme</code></td><td>Vue 2 梗图组件，<code>TierRanking</code> 完整实现，与 Vue 3 行为对齐</td></tr></tbody></table><p>梗图组件以 Vue 3 版本为主；Vue 2 包当前仅维护 <code>TierRanking</code>，新梗图组件不单独移植 Vue 2。</p><h2 id="提供的组件" tabindex="-1">提供的组件 <a class="header-anchor" href="#提供的组件" aria-label="Permalink to &quot;提供的组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件 / 分组</th><th>用途</th></tr></thead><tbody><tr><td><code>TierRanking</code>（Vue 3）</td><td>图片排行：上传压缩、跨评级拖拽、评级编辑、IndexedDB 持久化与按需截图</td></tr><tr><td><code>TierRanking</code>（Vue 2）</td><td>与 Vue 3 同名的具名导出，属性面板 schema 在各包 <code>src/components/TierRanking/propsSchema.json</code></td></tr><tr><td><code>MonsterDeleter</code>（Vue 3）</td><td>怪兽摧毁文件剧场：走路进场 → 指认确认 → 踹爆特效 + 音效 → 雷欧登场飞出；props <code>targets</code> / <code>bubbleText</code> / <code>choiceLabels</code> / <code>promptText</code>，事件 <code>completed</code>、<code>stage-change</code>，schema 在 <code>src/components/MonsterDeleter/propsSchema.json</code></td></tr><tr><td><code>IntensityCalibrator</code>（Vue 3）</td><td>浓度校准器：滑杆 0–30 推进六个阶段，阶段间立绘按透明度过渡，第五阶段转暗、第六阶段进入金圈祖先态；内置 <code>ikun</code> 与 <code>liang</code> 两套资源包，下拉即整体换肤</td></tr></tbody></table><h2 id="接入方式" tabindex="-1">接入方式 <a class="header-anchor" href="#接入方式" aria-label="Permalink to &quot;接入方式&quot;">​</a></h2><p>消费方按 hel 远程组件接入，先预加载再具名导入：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">preloadHelLibs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  deps: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;comps-vue2-meme&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, host: process.env.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">VUE_APP_MEME_HOST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, requiredExports: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;TierRanking&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { TierRanking } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@melt-js/comps-vue2-meme&#39;</span></span></code></pre></div><p>Vue 3 消费方把包名与 host 换成 <code>comps-vue3-meme</code> 即可；两包的 <code>hel_dist</code> 都提供独立 playground 页面，可直接打开调试。</p><h2 id="在线演示" tabindex="-1">在线演示 <a class="header-anchor" href="#在线演示" aria-label="Permalink to &quot;在线演示&quot;">​</a></h2><p>三个示例都收录在 <code>demo-vue3</code> 画廊，可分别打开体验：</p><table tabindex="0"><thead><tr><th>组件</th><th>演示地址</th></tr></thead><tbody><tr><td><code>TierRanking</code></td><td><a href="https://unpkg.com/@melt-js/demo-vue3/dist/index.html#/tier-ranking" target="_blank" rel="noreferrer">排行榜</a></td></tr><tr><td><code>MonsterDeleter</code></td><td><a href="https://unpkg.com/@melt-js/demo-vue3/dist/index.html#/monster-deleter" target="_blank" rel="noreferrer">怪兽剧场</a></td></tr><tr><td><code>IntensityCalibrator</code></td><td><a href="https://unpkg.com/@melt-js/demo-vue3/dist/index.html#/intensity-calibrator" target="_blank" rel="noreferrer">浓度校准器</a></td></tr></tbody></table><h2 id="浓度校准器" tabindex="-1">浓度校准器 <a class="header-anchor" href="#浓度校准器" aria-label="Permalink to &quot;浓度校准器&quot;">​</a></h2><p><code>IntensityCalibrator</code> 是可配置的整屏体验组件：<code>preset</code> 决定用哪套资源，<code>presets</code> 可以覆盖或追加自己的资源包。资源包含标题、顶部英文、强度标签、加载与滑杆提示、底部提示，以及六阶段各自的名称与图片。</p><table tabindex="0"><thead><tr><th>属性 / 事件</th><th>说明</th></tr></thead><tbody><tr><td><code>preset</code></td><td>资源包键，默认 <code>ikun</code>；配合 <code>v-model:preset</code> 双向绑定</td></tr><tr><td><code>presets</code></td><td>覆盖或新增资源包，结构与内置项一致（含 6 个 <code>stages</code>）</td></tr><tr><td><code>showSwitcher</code></td><td>是否在组件顶部渲染资源包下拉框，默认 <code>true</code></td></tr><tr><td><code>showSettings</code></td><td>是否显示「设置」按钮，可改标题、标签与六阶段名称 / 图片，默认 <code>true</code></td></tr><tr><td><code>persist</code></td><td>是否把设置写进 localStorage，默认 <code>false</code>（不写宿主存储）</td></tr><tr><td><code>storageKey</code></td><td>localStorage 前缀，默认 <code>melt-intensity-calibrator</code>，按 <code>storageKey:preset</code> 区分</td></tr><tr><td><code>level</code></td><td>当前浓度 0–30，配合 <code>v-model:level</code></td></tr><tr><td><code>preset-change</code></td><td>资源包切换完成，参数 <code>{ preset, label }</code></td></tr><tr><td><code>change</code></td><td>浓度变化，参数为当前数值</td></tr><tr><td><code>settings-saved</code></td><td>设置弹框保存，参数 <code>{ preset, settings }</code></td></tr></tbody></table><p>内置 <code>ikun</code>（练习生 → 初舞台 → 鸡哥 → 顶流坤 → 舞台王者 → 宗主）与 <code>liang</code>（小难梁 → 牢梁 → 梁子 → 梁圣 → 梁神 → 梁祖）两套，立绘随远程包下发；宿主只传 <code>preset</code> 就能换肤，传 <code>presets</code> 可再加第三套。组件需要约 880px 高度才不挤压立绘，嵌入面板时给足高度。</p>`,20)])])}const m=t(s,[["render",r]]);export{k as __pageData,m as default};
